pub mod differentiate {
    // Public API coverage for the complete scipy.differentiate inventory and gradient.
    use crate::common;
    use common::finite_close;
    use common::vector as numbers;

    use std::cell::Cell;

    use sci::{Error, differentiate as d, linalg};

    fn scalar(name: &str, x: f64) -> f64 {
        match name {
            "identity" => x,
            "sin" => x.sin(),
            "exp" => x.exp(),
            "cubic" => x.powi(3) - 2.0 * x,
            "square" => x * x,
            "constant" => 7.0,
            _ => panic!("unknown scalar fixture {name}"),
        }
    }

    fn objective(name: &str, x: &[f64]) -> f64 {
        match name {
            "linear" => x[0],
            "local_square" => (x[0] - 1.0).powi(2),
            "local_bilinear" => (x[0] - 1.0) * (x[1] - 1.0),
            "quadratic" => x[0].powi(2) + 3.0 * x[0] * x[1] + 2.0 * x[1].powi(2),
            "exp_product" => (x[0] * x[1]).exp(),
            "trig" => x[0].sin() * x[1].cos(),
            "rosen" => x
                .windows(2)
                .map(|v| 100.0 * (v[1] - v[0].powi(2)).powi(2) + (1.0 - v[0]).powi(2))
                .sum(),
            "quartic" => x[0].powi(4),
            "constant" => 7.0,
            _ => panic!("unknown objective fixture {name}"),
        }
    }

    fn vector(name: &str, x: &[f64]) -> Vec<f64> {
        match name {
            "identity_vector" => vec![x[0], 2.0 * x[0]],
            "vector" => vec![x[0] * x[1], x[0] + x[1]],
            "rectangular" => vec![x[0].sin(), x[0] * x[1], x[1].exp()],
            _ => panic!("unknown vector fixture {name}"),
        }
    }

    pub fn run(c: &[&str]) -> Vec<f64> {
        let fields = c;

        let point = numbers(fields[2]);
        let step = fields[3].parse().unwrap();
        let actual = match fields[0] {
            "derivative" => vec![vec![
                d::derivative(|x| scalar(fields[1], x), point[0], step).unwrap(),
            ]],
            "gradient" => vec![d::gradient(|x| objective(fields[1], x), &point, step).unwrap()],
            "jacobian" => d::jacobian(|x| vector(fields[1], x), &point, step).unwrap(),
            "hessian" => d::hessian(|x| objective(fields[1], x), &point, step).unwrap(),
            _ => panic!("unknown API"),
        };

        actual.into_iter().flatten().collect()
    }
}

#[allow(dead_code, unused_imports)]
pub mod filter {
    include!(concat!(env!("OUT_DIR"), "/filter.rs"));
    pub fn run(input: &[&str]) -> Vec<f64> {
        let a = &input[2..];
        match input[1] {
            "kalman_predict" => gaussian_values(kalman_predict(&g(a), &m(a[2]), &m(a[3])).unwrap()),
            "kalman_update" => update_values(
                kalman_update(&g(a), &v(a[2]), &m(a[3]), &m(a[4])).unwrap(),
                v(a[2]).len(),
            ),
            "extended_kalman_predict" => gaussian_values(
                extended_kalman_predict(&g(a), &m(a[2]), |x| model(x, a[3]), |x| jacobian(x, a[3]))
                    .unwrap(),
            ),
            "extended_kalman_update" => update_values(
                extended_kalman_update(
                    &g(a),
                    &v(a[2]),
                    &m(a[3]),
                    |x| model(x, a[4]),
                    |x| jacobian(x, a[4]),
                )
                .unwrap(),
                v(a[2]).len(),
            ),
            "unscented_kalman_step" => {
                let points = v(a[5]);
                update_values(
                    unscented_kalman_step(
                        &g(a),
                        &m(a[2]),
                        &v(a[3]),
                        &m(a[4]),
                        SigmaPoints {
                            alpha: points[0],
                            beta: points[1],
                            kappa: points[2],
                        },
                        |x| model(x, a[6]),
                        |x| {
                            if a[7] == "linear" {
                                Ok(x.to_vec())
                            } else {
                                model(x, a[7])
                            }
                        },
                    )
                    .unwrap(),
                    v(a[3]).len(),
                )
            }
            "particle_predict" => {
                let p = p(a);
                particle_values(
                    particle_predict(&p, |x| model(x, a[2])).unwrap(),
                    p.states.len(),
                    p.states[0].len(),
                )
            }
            "particle_update" => {
                let p = p(a);
                let mut ll = v(a[2]).into_iter();
                particle_values(
                    particle_update(&p, |_| Ok(ll.next().unwrap())).unwrap(),
                    p.states.len(),
                    p.states[0].len(),
                )
            }
            "particle_estimate" => gaussian_values(particle_estimate(&p(a)).unwrap()),
            "effective_sample_size" => vec![effective_sample_size(&p(a)).unwrap()],
            "systematic_resample" => {
                let p = p(a);
                particle_values(
                    systematic_resample(&p, a[2].parse().unwrap()).unwrap(),
                    p.states.len(),
                    p.states[0].len(),
                )
            }
            name => panic!("unknown fixture {name}"),
        }
    }
}
